WITH StoreSalesByProduct AS (SELECT product_id, AVG(revenue) AS avg_revenue, COUNT(*) AS num_store_sales FROM store_sales WHERE revenue BETWEEN 1700 AND 2800 GROUP BY product_id) SELECT products.id, products.price, products.cost, StoreSalesByProduct.avg_revenue, StoreSalesByProduct.num_store_sales FROM products INNER JOIN StoreSalesByProduct ON products.id = StoreSalesByProduct.product_id ORDER BY num_store_sales DESC, products.cost, id LIMIT 10
